/* CSS for Space 4K Background Theme */
body {
    background-image: url('https://www.google.com/url?sa=i&url=https%3A%2F%2F4kwallpapers.com%2Fspace%2F&psig=AOvVaw0hx90KVLgOt3VwrJ0PJIqf&ust=1730186924464000&source=images&cd=vfe&opi=89978449&ved=0CBEQjRxqFwoTCKCgudnGsIkDFQAAAAAdAAAAABAE'); /* Add a 4K space image URL */
    background-size: cover;           /* Cover the entire background */
    background-attachment: fixed;     /* Keep the background fixed when scrolling */
    background-position: center;      /* Center the image */
    background-repeat: no-repeat;     /* No repeating of the background */
    color: #ffffff;                   /* Optional: Change text color to white for readability */
}

/* Optional: Style specific elements for better theme consistency */
a, p, h1, h2, h3, h4, h5, h6 {
    color: #ffffff;                   /* Set text color to white for visibility on dark backgrounds */
}

a:hover {
    color: #ffd700;                   /* Optional: Change link color on hover for contrast */
}

/* Optional: Add a subtle space-like glow effect */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: radial-gradient(circle, rgba(0, 0, 0, 0) 60%, rgba(0, 0, 0, 0.8) 100%);
    pointer-events: none;             /* Make sure it's non-interactive */
}
